import { ValidationSummary, type ValidationIssue } from '@gntik-ai/blocks';
import { CircleCheck, Clock, Mail, MapPin, Phone, Send } from '@gntik-ai/icons';
import {
  Button,
  Card,
  CardBody,
  CardHeader,
  CardTitle,
  Field,
  FieldError,
  FieldLabel,
  Grid,
  Heading,
  Input,
  Link,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  Stack,
  Text,
  Textarea,
  type MegaMenuItem,
} from '@gntik-ai/ui';
import { useId, useState, type ReactNode } from 'react';
import { contactTopics, emptyContact, offices, publicCopyright, publicFooterLinks, publicMenu, validateContact, type ContactTopic, type ContactValues, type Office } from './data';
import { PublicFrame } from './PublicFrame';

export interface ContactProps {
  brand: ReactNode;
  menu: MegaMenuItem[];
  currentHref: string;
  title: string;
  description: string;
  topics: Array<{ value: ContactTopic; label: string }>;
  offices: Office[];
  defaultValues: Partial<ContactValues>;
  /** Called with valid values; the page shows the success state once it resolves. */
  onSubmit: (values: ContactValues) => void | Promise<void>;
  footerLinks: Array<{ label: string; href: string }>;
  copyright: ReactNode;
}

const LABELS: Record<keyof ContactValues, string> = { name: 'Name', email: 'Work email', company: 'Company', topic: 'Topic', message: 'Message' };

/** Public contact page: StackedLayout + MegaMenu, a validated form with a success state, and office cards. */
export default function ContactPage(props: Partial<ContactProps>) {
  const {
    brand,
    menu = publicMenu,
    currentHref = '/contact',
    title = 'Talk to us',
    description = 'Questions about plans, billing or a technical issue? We answer within one business day.',
    topics = contactTopics,
    offices: officeList = offices,
    defaultValues,
    onSubmit,
    footerLinks = publicFooterLinks,
    copyright = publicCopyright,
  } = props;
  const [values, setValues] = useState<ContactValues>({ ...emptyContact, ...defaultValues });
  const [submitCount, setSubmitCount] = useState(0);
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const ids = useId();
  const fieldId = (k: keyof ContactValues) => `${ids}-${k}`;

  const errors = submitCount > 0 ? validateContact(values) : {};
  const issues: ValidationIssue[] = (Object.keys(errors) as Array<keyof ContactValues>).map((k) => ({ fieldId: fieldId(k), label: LABELS[k], message: errors[k] ?? '' }));
  const set = <K extends keyof ContactValues>(key: K, value: ContactValues[K]) => setValues((v) => ({ ...v, [key]: value }));

  const submit = async () => {
    setSubmitCount((n) => n + 1);
    if (Object.keys(validateContact(values)).length > 0) return;
    setSending(true);
    try {
      await onSubmit?.(values);
      setSent(true);
    } finally {
      setSending(false);
    }
  };
  const reset = () => {
    setValues({ ...emptyContact, ...defaultValues });
    setSubmitCount(0);
    setSent(false);
  };

  return (
    <PublicFrame brand={brand} menu={menu} currentHref={currentHref} footerLinks={footerLinks} copyright={copyright}>
      <Stack gap={10}>
        <Stack gap={3} className="max-w-2xl">
          <Heading level={1} size="xl">
            {title}
          </Heading>
          <Text tone="muted">{description}</Text>
        </Stack>
        <Grid cols={{ base: 1, lg: 5 }} gap={8} align="start">
          <Card className="lg:col-span-3">
            <CardBody className="p-6">
              {sent ? (
                <div ref={(el) => el?.focus()} tabIndex={-1} role="status" className="flex flex-col items-start gap-3 py-6 outline-none">
                  <CircleCheck size={28} aria-hidden className="text-success-text" />
                  <Heading level={2} size="sm">
                    Message sent
                  </Heading>
                  <Text tone="muted">Thanks, {values.name.trim()}. We’ll reply to {values.email.trim()} within one business day.</Text>
                  <Button variant="secondary" onClick={reset}>
                    Send another message
                  </Button>
                </div>
              ) : (
                <form
                  noValidate
                  aria-label="Contact form"
                  onSubmit={(e) => {
                    e.preventDefault();
                    void submit();
                  }}
                >
                  <Stack gap={5}>
                    <ValidationSummary errors={issues} submitCount={submitCount} />
                    <Grid cols={{ base: 1, sm: 2 }} gap={4}>
                      <Field invalid={errors.name != null}>
                        <FieldLabel required>{LABELS.name}</FieldLabel>
                        <Input id={fieldId('name')} autoComplete="name" required value={values.name} onValueChange={(v) => set('name', v)} />
                        <FieldError match={errors.name != null}>{errors.name}</FieldError>
                      </Field>
                      <Field invalid={errors.email != null}>
                        <FieldLabel required>{LABELS.email}</FieldLabel>
                        <Input id={fieldId('email')} type="email" autoComplete="email" required value={values.email} onValueChange={(v) => set('email', v)} />
                        <FieldError match={errors.email != null}>{errors.email}</FieldError>
                      </Field>
                      <Field>
                        <FieldLabel>{LABELS.company}</FieldLabel>
                        <Input id={fieldId('company')} autoComplete="organization" value={values.company} onValueChange={(v) => set('company', v)} />
                      </Field>
                      <Field invalid={errors.topic != null}>
                        <FieldLabel required>{LABELS.topic}</FieldLabel>
                        <Select
                          value={values.topic || null}
                          onValueChange={(v) => set('topic', v ?? '')}
                          items={topics.map(({ value, label }) => ({ value, label }))}
                        >
                          <SelectTrigger id={fieldId('topic')} className="w-full" placeholder="Choose a topic" />
                          <SelectContent>
                            {topics.map((t) => (
                              <SelectItem key={t.value} value={t.value}>
                                {t.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FieldError match={errors.topic != null}>{errors.topic}</FieldError>
                      </Field>
                    </Grid>
                    <Field invalid={errors.message != null}>
                      <FieldLabel required>{LABELS.message}</FieldLabel>
                      <Textarea id={fieldId('message')} rows={5} required value={values.message} onValueChange={(v) => set('message', v)} />
                      <FieldError match={errors.message != null}>{errors.message}</FieldError>
                    </Field>
                    <Text variant="caption" tone="muted">
                      By sending this form you agree to our <Link href="/privacy">privacy policy</Link>.
                    </Text>
                    <div>
                      <Button type="submit" icon={Send} loading={sending}>
                        Send message
                      </Button>
                    </div>
                  </Stack>
                </form>
              )}
            </CardBody>
          </Card>
          <section aria-labelledby={`${ids}-offices`} className="lg:col-span-2">
            <Heading id={`${ids}-offices`} level={2} size="xs" className="mb-3">
              Offices
            </Heading>
            <Stack gap={3}>
              {officeList.map((o) => (
                <Card key={o.id} variant="outline">
                  <CardHeader>
                    <CardTitle as="h3">{o.city}</CardTitle>
                  </CardHeader>
                  <CardBody className="pt-0">
                    <ul className="flex flex-col gap-1.5">
                      <li className="flex gap-2">
                        <MapPin size={14} aria-hidden className="mt-1 shrink-0" />
                        <address className="not-italic">
                          {o.address.map((line) => (
                            <span key={line} className="block">
                              {line}
                            </span>
                          ))}
                        </address>
                      </li>
                      <li className="flex items-center gap-2">
                        <Mail size={14} aria-hidden className="shrink-0" />
                        <Link href={`mailto:${o.email}`}>{o.email}</Link>
                      </li>
                      <li className="flex items-center gap-2">
                        <Phone size={14} aria-hidden className="shrink-0" />
                        <Link href={`tel:${o.phone.replace(/\s/g, '')}`}>{o.phone}</Link>
                      </li>
                      <li className="flex items-center gap-2">
                        <Clock size={14} aria-hidden className="shrink-0" />
                        {o.hours}
                      </li>
                    </ul>
                  </CardBody>
                </Card>
              ))}
            </Stack>
          </section>
        </Grid>
      </Stack>
    </PublicFrame>
  );
}

import { Button, Link, Logo, MegaMenu, MobileNav, StackedLayout, ThemeSwitcher, megaMenuNavItems, type MegaMenuItem } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface PublicFrameProps {
  brand?: ReactNode;
  menu: MegaMenuItem[];
  currentHref?: string;
  signInHref?: string;
  getStartedHref?: string;
  footerLinks: Array<{ label: string; href: string }>;
  copyright: ReactNode;
  children: ReactNode;
}

/**
 * Public-site chrome: StackedLayout with the MegaMenu as the sub-nav row on large screens and
 * a MobileNav (fed by megaMenuNavItems) below lg.
 */
export function PublicFrame({
  brand = <Logo size={26} wordmark />,
  menu,
  currentHref,
  signInHref = '/sign-in',
  getStartedHref = '/sign-up',
  footerLinks,
  copyright,
  children,
}: PublicFrameProps) {
  return (
    <StackedLayout
      fullScreen
      width="wide"
      brand={brand}
      actions={
        <>
          <ThemeSwitcher size="sm" className="hidden md:inline-flex" />
          <Button variant="ghost" size="sm" render={<a href={signInHref} />} nativeButton={false}>
            Sign in
          </Button>
          <Button size="sm" render={<a href={getStartedHref} />} nativeButton={false}>
            Get started
          </Button>
          <MobileNav className="lg:hidden" groups={[{ items: megaMenuNavItems(menu) }]} currentHref={currentHref} title="Menu" label="Primary" side="right" />
        </>
      }
      subnav={<MegaMenu items={menu} currentHref={currentHref} label="Primary" className="hidden lg:block" />}
      footer={
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <span>{copyright}</span>
          <nav aria-label="Footer">
            <ul className="flex flex-wrap gap-x-4 gap-y-1">
              {footerLinks.map((l) => (
                <li key={l.href}>
                  <Link href={l.href} tone="muted" underline="hover">
                    {l.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        </div>
      }
    >
      {children}
    </StackedLayout>
  );
}

import { BarChart3, BookOpen, FileText, FolderKanban, LifeBuoy, Rocket, Shield } from '@gntik-ai/icons';
import type { MegaMenuItem } from '@gntik-ai/ui';

/** Public navigation: product panels plus plain links. */
export const publicMenu: MegaMenuItem[] = [
  {
    label: 'Product',
    sections: [
      {
        title: 'Build',
        links: [
          { label: 'Projects', href: '/product/projects', icon: FolderKanban, description: 'Every project, its environments and owners.' },
          { label: 'Deployments', href: '/product/deployments', icon: Rocket, description: 'Previews, rollbacks and deploy gates.' },
        ],
      },
      {
        title: 'Operate',
        links: [
          { label: 'Analytics', href: '/product/analytics', icon: BarChart3, description: 'Usage, latency and error budgets.' },
          { label: 'Security', href: '/product/security', icon: Shield, description: 'SSO, roles and audit logs.' },
        ],
      },
    ],
  },
  {
    label: 'Resources',
    sections: [
      {
        links: [
          { label: 'Documentation', href: '/docs', icon: BookOpen, description: 'Guides and API reference.' },
          { label: 'Changelog', href: '/changelog', icon: FileText, description: 'What shipped this month.' },
          { label: 'Support', href: '/contact', icon: LifeBuoy, description: 'Talk to a person.' },
        ],
      },
    ],
  },
  { label: 'Pricing', href: '/pricing' },
  { label: 'Contact', href: '/contact' },
];

export const publicFooterLinks = [
  { label: 'Status', href: '/status' },
  { label: 'Privacy', href: '/privacy' },
  { label: 'Terms', href: '/terms' },
];

export const publicCopyright = '© Example, Inc.';

export type ContactTopic = 'sales' | 'support' | 'billing' | 'partnerships';

export const contactTopics: Array<{ value: ContactTopic; label: string }> = [
  { value: 'sales', label: 'Sales and plans' },
  { value: 'support', label: 'Technical support' },
  { value: 'billing', label: 'Billing' },
  { value: 'partnerships', label: 'Partnerships' },
];

export interface ContactValues {
  name: string;
  email: string;
  company: string;
  topic: ContactTopic | '';
  message: string;
}

export const emptyContact: ContactValues = { name: '', email: '', company: '', topic: '', message: '' };

export interface Office {
  id: string;
  city: string;
  /** Address lines. */
  address: string[];
  email: string;
  phone: string;
  hours: string;
}

export const offices: Office[] = [
  { id: 'lisbon', city: 'Lisbon', address: ['Rua do Exemplo 120', '1200-000 Lisbon, Portugal'], email: 'lisbon@example.com', phone: '+351 210 000 000', hours: 'Mon–Fri, 9:00–18:00 WET' },
  { id: 'toronto', city: 'Toronto', address: ['200 Example Street, Suite 400', 'Toronto, ON M5V 0A0, Canada'], email: 'toronto@example.com', phone: '+1 416 000 0000', hours: 'Mon–Fri, 9:00–17:00 ET' },
  { id: 'singapore', city: 'Singapore', address: ['10 Example Road, #08-01', 'Singapore 018000'], email: 'singapore@example.com', phone: '+65 6000 0000', hours: 'Mon–Fri, 9:00–18:00 SGT' },
];

export type ContactErrors = Partial<Record<keyof ContactValues, string>>;

export function validateContact(v: ContactValues): ContactErrors {
  const errors: ContactErrors = {};
  if (!v.name.trim()) errors.name = 'Enter your name.';
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email.trim())) errors.email = 'Enter a valid email address.';
  if (!v.topic) errors.topic = 'Choose a topic.';
  if (v.message.trim().length < 10) errors.message = 'Tell us a little more (at least 10 characters).';
  return errors;
}
